func (o BlobSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Blobs.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Blob:
				o.copyMatchingRows(retrieved)
			case []*Blob:
				o.copyMatchingRows(retrieved...)
			case BlobSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Blob or a slice of Blob
				// then run the AfterDeleteHooks on the slice
				_, err = Blobs.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// MergeMod modifies a merge query to run BeforeMergeHooks and AfterMergeHooks
// and updates the slice with the returned rows.
func (o BlobSlice) MergeMod() bob.Mod[*dialect.MergeQuery] {
	return bob.ModFunc[*dialect.MergeQuery](func(q *dialect.MergeQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Blobs.BeforeMergeHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Blob:
				o.copyMatchingRows(retrieved)
			case []*Blob:
				o.copyMatchingRows(retrieved...)
			case BlobSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Blob or a slice of Blob
				// then run the AfterMergeHooks on the slice
				_, err = Blobs.AfterMergeHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))
	})
}

func (o BlobSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals BlobSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Blobs.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o BlobSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Blobs.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o BlobSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Blobs.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

// BlobLeases starts a query for related objects on blob_leases
func (o *Blob) BlobLeases(mods ...bob.Mod[*dialect.SelectQuery]) BlobLeasesQuery {
	return BlobLeases.Query(append(mods,
		sm.Where(BlobLeases.Columns.BlobID.EQ(psql.Arg(o.ID))),
	)...)
}

func (os BlobSlice) BlobLeases(mods ...bob.Mod[*dialect.SelectQuery]) BlobLeasesQuery {
	pkID := make(pgtypes.Array[string], 0, len(os))

	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "text[]"))

	return BlobLeases.Query(append(mods,
		sm.Where(BlobLeases.Columns.BlobID.EQ(PKArgExpr)),
	)...)
}

// ItemResource starts a query for related objects on resources
func (o *Blob) ItemResource(mods ...bob.Mod[*dialect.SelectQuery]) ResourcesQuery {
	return Resources.Query(append(mods,
		sm.Where(Resources.Columns.ID.EQ(psql.Arg(o.ItemID))),
	)...)
}

func (os BlobSlice) ItemResource(mods ...bob.Mod[*dialect.SelectQuery]) ResourcesQuery {
	pkItemID := make(pgtypes.Array[string], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenItemID := make(map[string]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenItemID[o.ItemID]; ok {
			continue
		}
		seenItemID[o.ItemID] = struct{}{}
		pkItemID = append(pkItemID, o.ItemID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkItemID), "text[]"))

	return Resources.Query(append(mods,
		sm.Where(Resources.Columns.ID.EQ(PKArgExpr)),
	)...)
}

