type blobWhere[Q psql.Filterable] struct {
	cols         blobColumns
	ID           psql.WhereMod[Q, string]
	CreatedAt    psql.WhereMod[Q, time.Time]
	Version      psql.WhereMod[Q, int64]
	ObjectKey    psql.WhereMod[Q, string]
	Filename     psql.WhereMod[Q, string]
	ContentType  psql.WhereMod[Q, string]
	Languages    psql.WhereMod[Q, string]
	Size         psql.WhereMod[Q, int64]
	Sha256       psql.WhereMod[Q, string]
	ItemID       psql.WhereMod[Q, string]
	Availability psql.WhereMod[Q, string]
	ReclaimAfter psql.WhereNullMod[Q, time.Time]
	R            blobWhereR[Q]
}

func (blobWhere[Q]) AliasedAs(alias string) blobWhere[Q] {
	return buildBlobWhere[Q](buildBlobColumns(alias))
}

func buildBlobWhere[Q psql.Filterable](cols blobColumns) blobWhere[Q] {
	return blobWhere[Q]{
		cols:         cols,
		ID:           psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:    psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		Version:      psql.Where[Q, int64](cols.Version.Expression),
		ObjectKey:    psql.Where[Q, string](cols.ObjectKey.Expression),
		Filename:     psql.Where[Q, string](cols.Filename.Expression),
		ContentType:  psql.Where[Q, string](cols.ContentType.Expression),
		Languages:    psql.Where[Q, string](cols.Languages.Expression),
		Size:         psql.Where[Q, int64](cols.Size.Expression),
		Sha256:       psql.Where[Q, string](cols.Sha256.Expression),
		ItemID:       psql.Where[Q, string](cols.ItemID.Expression),
		Availability: psql.Where[Q, string](cols.Availability.Expression),
		ReclaimAfter: psql.WhereNull[Q, time.Time](cols.ReclaimAfter.Expression),
		R:            blobWhereR[Q]{cols: cols},
	}
}

// blobWhereR holds the relationship-based filters of
// blobWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type blobWhereR[Q psql.Filterable] struct {
	cols blobColumns
}

// HasBlobLeases filters parents that have a matching BlobLeases using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to BlobLeases).
func (w blobWhereR[Q]) HasBlobLeases(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(BlobLeases.NameExpr()),
		sm.Where(BlobLeases.Columns.BlobID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasItemResource filters parents that have a matching ItemResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
